import {SOL,CURATED,esc,safeUrl,validAddress,parseInput,primaryPair,assess,fetchJSON,rpc,money,pct,short} from './core.js';
const paths={radar:'M12 3a9 9 0 1 0 9 9M12 7a5 5 0 1 0 5 5M12 12l8-8M16 3h5v5',files:'M8 3H4v14h3M10 7h10v14H10zM13 11h4M13 15h4',bookmark:'M6 3h12v18l-6-4-6 4V3Z',wallet:'M20 8V5H4a2 2 0 0 0 0 4h17v11H4a2 2 0 0 1-2-2V7M21 12h-6v4h6M17 14h.01',book:'M3 3h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v16h-6a4 4 0 0 0-3 2 4 4 0 0 0-3-2H3V3Zm9 2v16',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',sun:'M12 3V1m0 22v-2m9-9h2M1 12h2m15.4-6.4 1.4-1.4M4.2 19.8l1.4-1.4m12.8 0 1.4 1.4M4.2 4.2l1.4 1.4M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0Z',moon:'M20.9 13A9 9 0 0 1 11 3.1 9 9 0 1 0 20.9 13Z',arrow:'M5 12h14m-6-6 6 6-6 6',external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7',lock:'M5 10h14v11H5V10Zm3 0V7a4 4 0 0 1 8 0v3m-4 5v2',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Zm-4 10 3 3 5-6',check:'m5 12 4 4L19 6',circlecheck:'M22 11v1a10 10 0 1 1-6-9M8 11l4 4L22 5',activity:'M3 12h4l3-9 4 18 3-9h4',chart:'M4 3v18h17M8 16l4-5 4 3 5-8',list:'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01',grid:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z',refresh:'M20 8a9 9 0 1 0 .5 8M20 3v6h-6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',calendar:'M3 5h18v16H3zM7 2v6M17 2v6M3 11h18',code:'m8 7-5 5 5 5M16 7l5 5-5 5m-3-14-2 18',menu:'M3 6h18M3 12h18M3 18h18',x:'m6 6 12 12M6 18 18 6',copy:'M8 8h13v13H8zM16 8V3H3v13h5',download:'M12 3v12m-5-5 5 5 5-5M3 16v5h18v-5',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',warning:'m12 3 10 18H2L12 3Zm0 6v5m0 3h.01',info:'M12 11v6m0-10h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',globe:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0ZM2 12h20M12 2c6 6 6 14 0 20-6-6-6-14 0-20Z',bolt:'m13 2-9 12h7l-1 8 10-13h-7l0-7Z'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.info}"/></svg>`;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
function read(key,fallback){try{const raw=localStorage.getItem('proofprotocol.'+key)??localStorage.getItem('proofline.'+key);return raw===null?fallback:JSON.parse(raw)??fallback;}catch{return fallback;}}
const storage={checks:read('checks',[]),watch:read('watch',[]),theme:read('theme','dark'),density:read('density','comfortable')};
storage.checks=Array.isArray(storage.checks)?storage.checks.filter(r=>r&&validAddress(r.address)&&r.token&&r.assessment&&Array.isArray(r.assessment.checks)&&Number.isFinite(Date.parse(r.at))).slice(0,100):[];
storage.watch=Array.isArray(storage.watch)?storage.watch.filter(t=>t&&validAddress(t.address)).slice(0,90):[];
let market=[],marketError='',marketTime=null,marketLoading=false,activeMarket='all',view='grid',wallet=null,walletProvider=null,balance=null,renderEpoch=0,reportPending=new Set(),modalTrigger=null,closeListener=null;
const reports=new Map(storage.checks.map(r=>[r.address,r]));
function persist(key,value){storage[key]=value;try{localStorage.setItem('proofprotocol.'+key,JSON.stringify(value));}catch{toast('Browser storage is full or unavailable. Export your research to keep a copy.');}updateCounts();}
function updateCounts(){$('#checks-count').textContent=storage.checks.length;$('#watch-count').textContent=storage.watch.length;}
function applySettings(){document.documentElement.dataset.theme=storage.theme;document.body.classList.toggle('compact',storage.density==='compact');$('#theme-toggle').innerHTML=icon(storage.theme==='dark'?'sun':'moon');}applySettings();
$$('[data-icon]').forEach(el=>el.tagName==='A'?el.insertAdjacentHTML('afterbegin',icon(el.dataset.icon)):el.innerHTML=icon(el.dataset.icon));$('#copyright-year').textContent=new Date().getFullYear();
function toast(message){const el=document.createElement('div');el.className='toast';el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),4500);}
function route(){const value=location.hash.slice(1)||'/';return value.startsWith('/')?value:'/';}
function navigate(value){if(route()===value)render();else location.hash=value;}
function intro(title,description,action=''){return `<div class="page-intro"><div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${action||`<div class="date-label">${icon('calendar')}${new Date().toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}).toUpperCase()}</div>`}</div>`;}
function updateNavigation(){
 const r=route();
 $$('[data-route]').forEach(a=>{const active=a.dataset.route===r||(r.startsWith('/report/')&&a.dataset.route==='/checks');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 updateCounts();updateWalletLabel();
}
function updateWalletLabel(){ $('#wallet-label').textContent=wallet?short(wallet):'Connect wallet'; }
function scanForm(){return `<div class="scan-box"><form class="scan-form" id="scan-form">${icon('search')}<label class="sr-only" for="scan-input">Solana token address or project name</label><input id="scan-input" name="query" autocomplete="off" spellcheck="false" required maxlength="200" placeholder="Paste a token address or search a project"><button type="submit" class="primary-button">Get proof ${icon('arrow')}</button></form><div class="scan-bottom"><div class="examples"><span>Start with</span><button data-action="investigate" data-address="${SOL}">SOL</button><button data-action="investigate" data-address="${CURATED[2]}">BONK</button><button data-action="investigate" data-address="${CURATED[1]}">JUP</button></div><span class="scan-note">${icon('lock')} No wallet needed</span></div></div>`;}
function home(){
 const draft=$('#scan-input')?.value||'';const inputFocused=document.activeElement===$('#scan-input');const sol=market.find(p=>p.baseToken.address===SOL);
 $('#main').innerHTML=`<section class="hero" aria-labelledby="hero-heading"><span class="hero-label"><span class="network-dot"></span> BUILT FOR SOLANA. BACKED BY EVIDENCE.</span><h1 id="hero-heading">Less guessing.<br><span>More conviction.</span><svg class="conviction-arrow" viewBox="0 0 100 100" aria-hidden="true"><path d="m15 78 63-63M25 15h53v53" fill="none" stroke="currentColor" stroke-width="10" stroke-linecap="square"/></svg></h1><p>Find the signal before the noise finds you.<br>Scan a token. Check the facts. Keep the proof.</p>${scanForm()}<div class="hero-proof"><span>${icon('circlecheck')} Live market data</span><span>${icon('shield')} On-chain checks</span><span>${icon('files')} Reports you can keep</span></div></section>
 <div class="market-pulse"><span class="pulse-label"><span class="network-dot"></span> SOLANA MAINNET</span><span class="pulse-price">SOL <strong>${sol?money(sol.priceUsd):'—'}</strong>${sol?`<span class="${Number(sol.priceChange?.h24)>=0?'positive':'negative'}">${esc(pct(sol.priceChange?.h24))}</span>`:''}</span><span class="pulse-note">${sol?'24h change · largest indexed SOL pool':'Loading a live quote'}</span><a href="#/checks">${storage.checks.length} saved scan${storage.checks.length===1?'':'s'} ${icon('arrow')}</a></div>
 <section class="market-section" aria-labelledby="radar-title"><div class="section-header"><div><span class="eyebrow">YOUR NEXT DEEP DIVE</span><h2 id="radar-title">Find your signal.</h2></div><div class="section-controls"><button class="text-button" data-action="refresh-market" ${marketLoading?'disabled':''}>${icon('refresh')}Refresh</button><div class="view-options" role="group" aria-label="Market display"><button class="icon-button ${view==='grid'?'selected':''}" data-action="view" data-view="grid" aria-label="Card view" aria-pressed="${view==='grid'}">${icon('grid')}</button><button class="icon-button ${view==='list'?'selected':''}" data-action="view" data-view="list" aria-label="Table view" aria-pressed="${view==='list'}">${icon('list')}</button></div></div></div><div id="market-content">${marketContent()}</div><div class="market-footer"><span>Prices & pools via <a href="https://dexscreener.com" target="_blank" rel="noopener noreferrer">DEX Screener ${icon('external')}</a></span><span>${marketTime?'Updated '+marketTime.toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit',hour12:false}):marketError?'Source unavailable':'Fetching live data…'}</span></div></section>
 <section class="how-strip" aria-label="Three steps to better research"><div><span>01</span><strong>Find a token.</strong><p>Paste a contract. Or search a name.</p></div><div><span>02</span><strong>Read the signals.</strong><p>Permissions. Liquidity. Activity.</p></div><div><span>03</span><strong>Keep your proof.</strong><p>Save, watch, and revisit.</p></div><a href="#/methodology" aria-label="Read the methodology">${icon('arrow')}</a></section>
 <div class="closing-note">Conviction is earned.<br><span>Start with PROOF.</span><button class="text-button" data-action="focus-search">Scan your first token ${icon('arrow')}</button></div>`;
 if($('#scan-input')){$('#scan-input').value=draft;if(inputFocused)$('#scan-input').focus();}
 if(!marketLoading&&!marketTime&&!marketError)loadMarket();
}
function tokenIcon(token,pair,size=''){const url=safeUrl(pair?.info?.imageUrl);return url?`<img class="token-icon ${size}" src="${esc(url)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:`<span class="token-icon ${size}" aria-hidden="true">${esc((token.symbol||'?').slice(0,2))}</span>`;}
function tokenCell(p){return `<div class="token-cell">${tokenIcon(p.baseToken,p)}<div><span class="token-name">${esc(p.baseToken.symbol)} <small>SOL</small></span><span class="token-address">${esc(short(p.baseToken.address,5))}</span></div></div>`;}
function watched(address){return storage.watch.some(t=>t.address===address);}
function watchButton(p){const yes=watched(p.baseToken.address);return `<button class="icon-button ${yes?'bookmarked':''}" data-action="watch" data-address="${esc(p.baseToken.address)}" aria-label="${yes?'Remove '+esc(p.baseToken.symbol)+' from':'Add '+esc(p.baseToken.symbol)+' to'} watchlist" aria-pressed="${yes}">${icon('bookmark')}</button>`;}
function marketRows(pairs){if(view==='grid')return `<div class="card-grid">${pairs.map(p=>`<article class="market-card"><div class="card-top">${tokenCell(p)}${watchButton(p)}</div><div class="card-data"><div><small>PRICE</small><strong class="mono">${money(p.priceUsd)}</strong></div><div><small>24H CHANGE</small><strong class="mono ${Number(p.priceChange?.h24)>=0?'positive':'negative'}">${esc(pct(p.priceChange?.h24))}</strong></div><div><small>LIQUIDITY</small><strong class="mono">${money(p.liquidity?.usd,true)}</strong></div></div><button class="inspect-button" data-action="investigate" data-address="${esc(p.baseToken.address)}">Scan token ${icon('arrow')}</button></article>`).join('')}</div>`;
 return `<div class="scroll-table"><table class="market-table"><thead><tr><th>PROJECT</th><th>PRICE</th><th>24H CHANGE</th><th class="hide-small">LIQUIDITY</th><th class="hide-medium">SAVED REPORT</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${pairs.map(p=>`<tr><td>${tokenCell(p)}</td><td class="mono">${money(p.priceUsd)}</td><td class="mono ${Number(p.priceChange?.h24)>=0?'positive':'negative'}">${esc(pct(p.priceChange?.h24))}</td><td class="mono hide-small">${money(p.liquidity?.usd,true)}</td><td class="hide-medium"><span class="research-state">${icon(reports.has(p.baseToken.address)?'circlecheck':'clock')}${reports.has(p.baseToken.address)?'Report saved':'Not scanned'}</span></td><td><div class="table-actions">${watchButton(p)}<button class="inspect-button" data-action="investigate" data-address="${esc(p.baseToken.address)}">Scan ${icon('arrow')}</button></div></td></tr>`).join('')}</tbody></table></div>`;}
function empty(title,message,name='files',action='Scan a token',target='/'){return `<div class="empty-state">${icon(name)}<h2>${esc(title)}</h2><p>${esc(message)}</p>${action?`<a class="primary-button" href="#${target}">${esc(action)} ${icon('arrow')}</a>`:''}</div>`;}
function loadingRows(){return `<div aria-label="Loading live market data" role="status">${Array.from({length:4},()=>'<div class="loading-row"><span class="skeleton"></span><span class="skeleton"></span><span class="skeleton"></span></div>').join('')}</div>`;}
function marketContent(){if(marketError)return `<div class="error-box"><strong>Market data is temporarily unavailable</strong>${esc(marketError)}<br><button class="secondary-button" data-action="refresh-market">Try again ${icon('refresh')}</button></div>`;if(!market.length)return loadingRows();const pairs=activeMarket==='all'?market:market.filter(p=>watched(p.baseToken.address));return pairs.length?marketRows(pairs):empty('Keep your signals close','Bookmark a project to add it to your personal watchlist.','bookmark','','/');}
async function loadMarket(force=false){if(marketLoading)return;marketLoading=true;marketError='';try{const pairs=await fetchJSON('https://api.dexscreener.com/tokens/v1/solana/'+CURATED.join(','));if(!Array.isArray(pairs))throw new Error('The market source returned an unexpected response.');market=CURATED.map(a=>primaryPair(pairs,a)).filter(Boolean);if(!market.length)throw new Error('The market source returned no matching token pools.');marketTime=new Date();}catch(e){marketError=e.message;if(force)toast(e.message);}finally{marketLoading=false;if(route()==='/')home();}}
function investigationList(){const q=$('#history-filter')?.value||'';const checks=storage.checks.filter(r=>(r.token.name+' '+r.token.symbol+' '+r.address).toLowerCase().includes(q.toLowerCase()));return checks.map(r=>`<article class="history-item">${tokenIcon(r.token,r.pair)}<div><h3>${esc(r.token.name)} <span class="token-address">${esc(r.token.symbol)} · ${esc(short(r.address,6))}</span></h3><p>${new Date(r.at).toLocaleDateString('en-US',{month:'short',day:'numeric'})} · ${esc(r.assessment.title)}</p></div><a class="inspect-button" href="#/report/${esc(r.address)}">Open report ${icon('external')}</a><button class="icon-button" data-action="delete-report" data-address="${esc(r.address)}" aria-label="Delete ${esc(r.token.symbol)} report">${icon('trash')}</button></article>`).join('')||'<p class="search-label">No investigations match this filter.</p>';}
function checks(){const action=`<a class="primary-button" href="#/">New scan ${icon('arrow')}</a>`;$('#main').innerHTML=intro('Saved scans','Your research. Ready when you are.',action)+(storage.checks.length?`<div class="toolbar-filter"><label class="sr-only" for="history-filter">Filter investigations</label><input id="history-filter" type="search" placeholder="Filter by name, ticker or address…"></div><div class="report-history" id="history-list">${investigationList()}</div>`:empty('Your proof starts here','Scan a Solana token. Your report will be saved here to revisit or export.'));}
async function watchlist(){const epoch=renderEpoch;$('#main').innerHTML=intro('Your watchlist','Keep an eye on the projects that matter to you.',`<a class="primary-button" href="#/">Discover projects ${icon('arrow')}</a>`)+(storage.watch.length?`<div id="watch-content">${loadingRows()}</div>`:empty('Keep your signals close','Use the bookmark beside a project to save it here. Your watchlist stays in this browser.','bookmark','Explore projects'));if(!storage.watch.length)return;try{const addresses=storage.watch.map(t=>t.address);const batches=[];for(let i=0;i<addresses.length;i+=30)batches.push(addresses.slice(i,i+30));const data=(await Promise.all(batches.map(b=>fetchJSON('https://api.dexscreener.com/tokens/v1/solana/'+b.join(','))))).flat();if(renderEpoch!==epoch)return;const pairs=addresses.map(a=>primaryPair(data,a)).filter(Boolean);$('#watch-content').innerHTML=pairs.length?marketRows(pairs):empty('No current market data','The market source did not return matching pools. Your bookmarks are still saved.','info','Explore projects');const absent=storage.watch.filter(t=>!pairs.some(p=>p.baseToken.address===t.address));if(absent.length)$('#watch-content').insertAdjacentHTML('beforeend',absent.map(t=>`<div class="history-item"><div><strong>${esc(t.symbol||short(t.address))}</strong><p>Market data unavailable · ${esc(short(t.address,6))}</p></div><button class="secondary-button" data-action="watch" data-address="${esc(t.address)}">Remove</button></div>`).join(''));}catch(e){if(renderEpoch===epoch)$('#watch-content').innerHTML=`<div class="error-box"><strong>Unable to refresh your watchlist</strong>${esc(e.message)}<br><button class="secondary-button" data-action="retry-watchlist">Try again</button></div>`;}}
function account(){const connected=wallet&&walletProvider;$('#main').innerHTML=intro('Your account','Your wallet, your workspace, your rules.')+`<div class="account-grid"><div><section class="panel"><div class="panel-header"><h2>Wallet</h2>${connected?'<span class="connection-status"><span class="network-dot"></span> Connected</span>':'<span class="local-badge">READ-ONLY</span>'}</div><div class="panel-body">${connected?`<h3>Connected to Solana</h3><div class="address-box"><code>${esc(wallet)}</code><button class="icon-button" data-action="copy" data-value="${esc(wallet)}" aria-label="Copy wallet address">${icon('copy')}</button></div><div class="balance">${balance===null?'—':balance.toLocaleString('en-US',{maximumFractionDigits:5})} <span class="positive">SOL</span></div><p>${balance===null?'Balance unavailable. You can retry the public mainnet RPC.':'Mainnet balance · fetched from Solana RPC'}</p><div class="button-row"><a href="https://solscan.io/account/${esc(wallet)}" class="secondary-button" target="_blank" rel="noopener noreferrer">View on Solscan ${icon('external')}</a><button class="secondary-button" data-action="refresh-balance">${icon('refresh')} Refresh</button><button class="danger-button" data-action="disconnect-wallet">Disconnect</button></div>`:`<div class="wallet-illustration">${icon('wallet')}</div><h3>Your wallet. Always in your control.</h3><p>Connect Phantom or Solflare to view your Solana mainnet address and balance. Your research works with or without a wallet.</p><button class="primary-button" data-action="connect-wallet">${icon('wallet')} Connect wallet ${icon('arrow')}</button>`}<p class="wallet-note">${icon('lock')} No message signatures, transactions, or token approvals.</p></div></section><section class="panel"><div class="panel-header"><h2>Your research library</h2><span class="local-badge">THIS BROWSER</span></div><div class="panel-body"><div class="settings-stat"><div><strong>${String(storage.checks.length).padStart(2,'0')}</strong><small>Investigations</small></div><div><strong>${String(storage.watch.length).padStart(2,'0')}</strong><small>Watchlist projects</small></div></div><p>Reports and watchlists are stored on this device. Wallet connection does not sync them. Export a copy to keep your evidence.</p><div class="button-row"><button class="secondary-button" data-action="export-library">${icon('download')} Export research</button><button class="danger-button" data-action="clear-library">Clear local data</button></div></div></section></div><div><section class="panel"><div class="panel-header"><h2>Workspace settings</h2>${icon('sun')}</div><div class="panel-body"><div class="settings-row"><div><strong>Appearance</strong><p>Make the desk your own.</p></div><label class="sr-only" for="theme-setting">Color theme</label><select id="theme-setting" class="select"><option value="dark" ${storage.theme==='dark'?'selected':''}>Dark</option><option value="light" ${storage.theme==='light'?'selected':''}>Light</option></select></div><div class="settings-row"><div><strong>Table density</strong><p>A little more room, or a little less.</p></div><label class="sr-only" for="density-setting">Table density</label><select id="density-setting" class="select"><option value="comfortable" ${storage.density!=='compact'?'selected':''}>Comfortable</option><option value="compact" ${storage.density==='compact'?'selected':''}>Compact</option></select></div><div class="settings-row"><div><strong>Network</strong><p>All research uses real mainnet data.</p></div><span class="connection-status"><span class="network-dot"></span>Solana</span></div></div></section><section class="panel"><div class="panel-header"><h2>Built on evidence</h2>${icon('shield')}</div><div class="panel-body"><p>Proof Protocol checks observable token permissions and indexed markets. It does not certify projects, hold funds, or promise returns.</p><a href="#/methodology" class="text-button">Understand every signal ${icon('external')}</a></div></section><div class="bottom-banner">${icon('info')}<div><strong>Proof Protocol · PROOF</strong><p>Project ticker: PROOF. Official token contract is not configured.</p></div></div></div></div>`;}
function methodology(){$('#main').innerHTML=intro('Evidence over hype.','An open methodology. No mystery scores.')+`<div class="prose"><section class="panel"><div class="panel-body"><span class="eyebrow">THE PROOF APPROACH</span><h3>Know what’s checked. Know what isn’t.</h3><p>Proof Protocol is an independent Solana research workspace inspired by the idea that every claim deserves evidence. Its reports are deterministic data checks, not an AI audit or a financial recommendation.</p></div></section><div class="method-step"><span>01 /</span><div><h2>Start with the exact address.</h2><p>Paste a Solana mint address, a Solscan token link, or search for a project. Names and tickers can be copied. Always confirm the contract address through an independent official source. DEX Screener pair links are resolved to their base token.</p></div></div><div class="method-step"><span>02 /</span><div><h2>Read the permissions.</h2><p>We request the parsed mint account from <a href="https://solana.com/docs/rpc/http/getaccountinfo" target="_blank" rel="noopener noreferrer">Solana mainnet RPC ↗</a>. An active mint authority can increase supply; an active freeze authority can freeze eligible accounts. Revoked authorities reduce those specific powers, but do not establish safety. Token-2022 extensions need additional review.</p></div></div><div class="method-step"><span>03 /</span><div><h2>Follow the market evidence.</h2><p><a href="https://docs.dexscreener.com/api/reference" target="_blank" rel="noopener noreferrer">DEX Screener ↗</a> provides prices, volume, liquidity, trading activity and pool age. We select the largest indexed base-token pool by reported USD liquidity. Figures describe that pool, not the whole token market. Liquidity below $100,000 and pool age under seven days are flagged for review. These thresholds are research heuristics.</p></div></div><div class="method-step"><span>04 /</span><div><h2>Leave room for the unknown.</h2><p>We do not verify teams, business claims, product functionality, contract source code, liquidity locks, holder concentration, wash trading or rug-pull risk. A report with no flagged signals is not a clean bill of health. Unavailable data is labeled unknown. Missing API fields are never treated as positive evidence.</p></div></div><div class="method-step"><span>05 /</span><div><h2>Keep the receipts.</h2><p>Every report includes its sources and timestamp. Reports and watchlists are stored in your browser and can be exported. Saved reports are snapshots; use Refresh evidence to fetch new data. Public APIs can be rate limited or unavailable, and indexed data can lag the chain.</p></div></div><div class="bottom-banner">${icon('lock')}<div><strong>Connection is read-only.</strong><p>Proof Protocol requests wallet access and balance data. It never asks you to sign a message, approve a token, or send a transaction.</p></div></div></div>`;}
async function submitQuery(query){const parsed=parseInput(query);if(parsed.type==='address'){startInvestigation(parsed.value);return;}if(parsed.type==='pair'){navigate('/search?q='+encodeURIComponent(query));return;}if(parsed.type==='unsupported'){toast('Use a Solana mint address, a Solscan link, a DEX Screener Solana link, or a project name. Website and social claims need manual review.');return;}if(parsed.type==='invalid'){toast('Enter a valid Solana token address or a project name with at least 2 characters.');return;}if(/^[1-9A-HJ-NP-Za-km-z]{30,50}$/.test(parsed.value)){toast('That address does not decode to a 32-byte Solana public key. Check the full mint address.');return;}navigate('/search?q='+encodeURIComponent(parsed.value));}
async function searchPage(){const epoch=renderEpoch;const q=new URLSearchParams(route().split('?')[1]).get('q')||'';$('#main').innerHTML=intro('Find the project. Check the address.','Names can be copied. A contract address is the starting point.')+`<form id="project-search" class="inline-search"><label class="sr-only" for="project-query">Search Solana projects</label><input id="project-query" name="query" value="${esc(q)}" placeholder="Search Solana projects…" required maxlength="200"><button class="primary-button" type="submit">Search ${icon('search')}</button></form><div id="search-content">${loadingRows()}</div>`;try{const parsed=parseInput(q);let pairs;if(parsed.type==='pair'){const data=await fetchJSON('https://api.dexscreener.com/latest/dex/pairs/solana/'+parsed.value);pairs=data.pairs||[];}else{const data=await fetchJSON('https://api.dexscreener.com/latest/dex/search?q='+encodeURIComponent(q));pairs=data.pairs||[];}if(renderEpoch!==epoch)return;const byAddress=new Map();pairs.filter(p=>p.chainId==='solana'&&validAddress(p.baseToken?.address||'')).sort((a,b)=>(Number(b.liquidity?.usd)||0)-(Number(a.liquidity?.usd)||0)).forEach(p=>{if(!byAddress.has(p.baseToken.address))byAddress.set(p.baseToken.address,p);});const results=[...byAddress.values()].slice(0,20);window.searchPairs=results;$('#search-content').innerHTML=results.length?`<p class="search-label"><strong>${results.length} Solana result${results.length===1?'':'s'}</strong> for “${esc(q)}” · Verify addresses independently. Listings are not endorsements.</p>${marketRows(results)}`:empty('No matching Solana markets','Try the exact mint address or a different ticker. Newly created or unindexed tokens may not appear.','search','Back to research');}catch(e){if(renderEpoch===epoch)$('#search-content').innerHTML=`<div class="error-box"><strong>Search is temporarily unavailable</strong>${esc(e.message)}<button class="secondary-button" data-action="retry-search">Try again</button></div>`;}}
function reportLoading(address){$('#main').innerHTML=`<a class="text-button" href="#/">← Back to research</a><div class="loading-investigation" role="status"><div class="scan-animation">${icon('radar')}</div><span class="eyebrow">FOLLOWING THE EVIDENCE</span><h1>Let’s see what’s on-chain.</h1><p class="mono">${esc(short(address,10))}</p><div class="progress-steps"><div class="active">${icon('check')} Solana mainnet address validated</div><div>${icon('activity')} Fetching indexed market evidence</div><div>${icon('shield')} Reading mint and freeze authorities</div><div>${icon('files')} Building your evidence report</div></div><p>Public data only. No wallet connection required.</p></div>`;}
async function startInvestigation(address,force=false){if(!validAddress(address)){toast('Please provide a valid Solana mint address.');return;}if(force)reports.delete(address);if(route()!=='/report/'+address)navigate('/report/'+address);else render();}
async function reportPage(address){if(!validAddress(address)){$('#main').innerHTML=empty('Invalid token address','This report link does not contain a valid Solana public key.','warning');return;}const existing=reports.get(address);if(existing){renderReport(existing);return;}reportLoading(address);if(reportPending.has(address))return;reportPending.add(address);try{const [dexResult,chainResult]=await Promise.allSettled([fetchJSON('https://api.dexscreener.com/latest/dex/tokens/'+address),rpc('getAccountInfo',[address,{encoding:'jsonParsed',commitment:'confirmed'}])]);const dex=dexResult.status==='fulfilled'?dexResult.value:null;const chain=chainResult.status==='fulfilled'?chainResult.value:null;const pair=primaryPair(dex?.pairs,address);if(!pair&&chain?.value?.data?.parsed?.type!=='mint'){if(chainResult.status==='fulfilled')throw new Error(chain?.value?'This address is not a supported parsed SPL token mint. Try the token’s mint address instead of a wallet or pool address.':'This account was not found on Solana mainnet. Confirm the exact token mint address.');throw new Error('Neither a matching indexed market nor a parsed on-chain mint could be retrieved. The public sources may be unavailable. Please retry.');}
 const token=pair?.baseToken||{address,symbol:'SPL',name:'Unindexed SPL token'};const report={schema:1,address,token,pair,chain,at:new Date().toISOString(),assessment:assess(pair,chain,address,dexResult.status==='fulfilled')};reports.set(address,report);persist('checks',[report,...storage.checks.filter(r=>r.address!==address)].slice(0,100));if(route()==='/report/'+address)renderReport(report);
 }catch(e){if(route()==='/report/'+address)$('#main').innerHTML=intro('Evidence unavailable','The sources did not return enough data for this scan.')+`<div class="error-box"><strong>This check needs another look</strong>${esc(e.message)}<div class="button-row"><button class="secondary-button" data-action="retry-report" data-address="${esc(address)}">${icon('refresh')} Retry check</button><a class="secondary-button" href="#/">Back to research</a></div></div>`;}finally{reportPending.delete(address);}}
function renderReport(r){const p=r.pair,a=r.assessment;const yes=watched(r.address);$('#main').innerHTML=`<a class="text-button" href="#/checks">← Saved scans</a><div class="report-top"><div class="report-token">${tokenIcon(r.token,p,'large')}<div><h1>${esc(r.token.name)}</h1><span class="token-address">${esc(r.token.symbol)} · SOLANA MAINNET · ${esc(short(r.address,6))} <button class="text-button" data-action="copy" data-value="${esc(r.address)}" aria-label="Copy token address">Copy address ${icon('copy')}</button></span></div></div><div class="button-row"><button class="secondary-button ${yes?'bookmarked':''}" data-action="watch" data-address="${esc(r.address)}">${icon('bookmark')}${yes?'Watching':'Watch project'}</button><button class="secondary-button" data-action="export-report" data-address="${esc(r.address)}">${icon('download')}Export</button><button class="primary-button" data-action="retry-report" data-address="${esc(r.address)}">${icon('refresh')}Refresh evidence</button></div></div><div class="report-date">EVIDENCE SNAPSHOT · ${new Date(r.at).toLocaleString('en-US',{timeZone:'UTC',month:'short',day:'numeric',year:'numeric',hour:'2-digit',minute:'2-digit',hour12:false})} UTC · SAVED IN THIS BROWSER</div><section class="report-summary ${a.flags?'caution':''}">${icon(a.flags?'warning':'shield')}<div><span class="eyebrow">${a.flags} FLAGGED · ${a.missing} NEED${a.missing===1?'S':''} MANUAL REVIEW · DETERMINISTIC CHECK</span><h2>${esc(a.title)}</h2><p>${esc(a.summary)}</p></div></section><div class="report-grid"><section class="panel"><div class="panel-header"><h2>The evidence</h2><span class="local-badge">SOURCE-LINKED</span></div>${a.checks.map(c=>`<div class="evidence-item">${icon(c.status==='pass'?'circlecheck':c.status==='caution'?'warning':'info',c.status==='pass'?'positive':c.status==='caution'?'negative':'')}<div><strong>${esc(c.name)} <span class="local-badge">${c.status==='pass'?'OBSERVED':c.status==='caution'?'REVIEW':c.status==='info'?'CONTEXT':'UNKNOWN'}</span></strong><p>${esc(c.detail)}</p><small>${esc(c.source)}</small></div></div>`).join('')}</section><div><section class="panel"><div class="panel-header"><h2>Market snapshot</h2><span class="local-badge">LARGEST INDEXED POOL</span></div><div class="panel-body"><div class="report-metrics"><div><small>Price</small><strong>${money(p?.priceUsd)}</strong></div><div><small>24h change</small><strong class="${Number(p?.priceChange?.h24)>=0?'positive':'negative'}">${esc(pct(p?.priceChange?.h24))}</strong></div><div><small>Pool liquidity</small><strong>${money(p?.liquidity?.usd,true)}</strong></div><div><small>24h pool volume</small><strong>${money(p?.volume?.h24,true)}</strong></div><div><small>Market cap</small><strong>${money(p?.marketCap,true)}</strong></div><div><small>Pool / venue</small><strong>${esc(p?.dexId||'—')}</strong></div></div><p class="report-note">These figures describe the selected pool. They can change quickly and may lag the chain.</p></div></section><section class="panel"><div class="panel-header"><h2>Check the sources</h2>${icon('external')}</div><div class="panel-body"><a class="report-source" href="https://solscan.io/token/${esc(r.address)}" target="_blank" rel="noopener noreferrer">Solscan <span>Mint account ↗</span></a>${safeUrl(p?.url)?`<a class="report-source" href="${esc(safeUrl(p.url))}" target="_blank" rel="noopener noreferrer">DEX Screener <span>Pool & market evidence ↗</span></a>`:''}<a class="report-source" href="https://explorer.solana.com/address/${esc(r.address)}" target="_blank" rel="noopener noreferrer">Solana Explorer <span>Mainnet account ↗</span></a>${(p?.info?.websites||[]).filter(w=>safeUrl(w.url)).slice(0,2).map(w=>`<a class="report-source" href="${esc(safeUrl(w.url))}" target="_blank" rel="noopener noreferrer">Project website <span>Unverified external claim ↗</span></a>`).join('')}</div></section><div class="bottom-banner">${icon('info')}<div><strong>A signal is a starting point.</strong><p>No flags does not mean no risk. Read the <a href="#/methodology">methodology ↗</a>.</p></div></div></div></div>`;}
function render(){renderEpoch++;updateNavigation();const r=route();if(r==='/')home();else if(r==='/me')account();else if(r==='/checks')checks();else if(r==='/watchlist')watchlist();else if(r==='/methodology')methodology();else if(r.startsWith('/report/'))reportPage(r.split('/')[2]);else if(r.startsWith('/search?'))searchPage();else{$('#main').innerHTML=empty('This page is off the radar','Head back to your research desk to continue.','search');}window.scrollTo(0,0);}
function openModal(title,body){modalTrigger=document.activeElement;$('#modal').innerHTML=`<div class="modal-header"><h2 id="modal-title">${esc(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('x')}</button></div>${body}`;$('#modal-overlay').hidden=false;document.body.style.overflow='hidden';setTimeout(()=>$('#modal button, #modal input, #modal a')?.focus(),0);}
function closeModal(){if(closeListener){closeListener();closeListener=null;}$('#modal-overlay').hidden=true;document.body.style.overflow='';modalTrigger?.focus();}
function walletModal(){if(wallet){navigate('/me');return;}openModal('Connect your wallet',`<p>View your Solana mainnet address and balance. Your wallet stays in your control.</p><button class="wallet-option" data-action="choose-wallet" data-provider="phantom"><span>◕</span>Phantom <small>${window.phantom?.solana?.isPhantom||window.solana?.isPhantom?'Detected':'Open wallet site ↗'}</small></button><button class="wallet-option solflare" data-action="choose-wallet" data-provider="solflare"><span>☀</span>Solflare <small>${window.solflare?.isSolflare?'Detected':'Open wallet site ↗'}</small></button><p class="modal-fine">Connection requests access to your public address. Proof Protocol does not request signatures, approvals, or transactions.</p>`);}
async function connectWallet(name){const provider=name==='phantom'?(window.phantom?.solana||(window.solana?.isPhantom?window.solana:null)):(window.solflare?.isSolflare?window.solflare:null);if(!provider){window.open(name==='phantom'?'https://phantom.com':'https://solflare.com','_blank','noopener,noreferrer');toast('Install or open the wallet, then return to connect. On mobile, use its in-app browser.');return;}try{const result=await provider.connect();const address=(result?.publicKey||provider.publicKey)?.toString();if(!validAddress(address||''))throw new Error('The wallet did not return a valid Solana address.');wallet=address;walletProvider=provider;balance=null;updateWalletLabel();provider.on?.('accountChanged',walletChanged);provider.on?.('disconnect',walletDisconnected);closeModal();toast('Wallet connected. Read-only access.');navigate('/me');await refreshBalance();}catch(e){toast(e.code===4001?'Wallet connection cancelled.':e.message||'Unable to connect this wallet.');}}
function walletChanged(key){if(!key){walletDisconnected();return;}const address=key.toString();if(!validAddress(address)){walletDisconnected();return;}wallet=address;balance=null;updateWalletLabel();if(route()==='/me')account();refreshBalance();}
function walletDisconnected(){walletProvider?.removeListener?.('accountChanged',walletChanged);walletProvider?.removeListener?.('disconnect',walletDisconnected);wallet=null;walletProvider=null;balance=null;updateWalletLabel();if(route()==='/me')account();}
async function refreshBalance(){if(!wallet)return;const address=wallet;try{const r=await rpc('getBalance',[address,{commitment:'confirmed'}]);if(wallet!==address)return;balance=Number(r.value)/1e9;if(route()==='/me')account();}catch{toast('The public mainnet RPC could not fetch this balance. Try again shortly.');}}
function download(name,value){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'});const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function toggleWatch(address){if(watched(address)){persist('watch',storage.watch.filter(t=>t.address!==address));toast('Project removed from your watchlist.');}else{if(storage.watch.length>=90){toast('Your watchlist holds up to 90 projects. Remove one before adding another.');return;}const p=[...market,...(window.searchPairs||[])].find(p=>p.baseToken.address===address);const report=reports.get(address);const token=p?.baseToken||report?.token||{symbol:short(address),name:short(address)};persist('watch',[...storage.watch,{address,symbol:token.symbol,name:token.name}]);toast('Project added to your watchlist.');}const r=route();if(r==='/')home();else if(r.startsWith('/report/')){const report=reports.get(address);if(report)renderReport(report);}else if(r==='/watchlist')watchlist();else if(r.startsWith('/search')){const q=new URLSearchParams(r.split('?')[1]).get('q')||'';const results=window.searchPairs||[];$('#search-content').innerHTML=`<p class="search-label"><strong>${results.length} Solana results</strong> for “${esc(q)}” · Verify addresses independently.</p>${marketRows(results)}`;}}
const actions={
'investigate':el=>startInvestigation(el.dataset.address),
'focus-search':()=>quickSearch(),
 'token-info':()=>openModal('Proof Protocol · PROOF',`<div class="token-brand-badge">$PROOF</div><p>PROOF is the project ticker for Proof Protocol.</p><p>An official Solana token contract has not been configured. No token price, supply, or purchase link is published here.</p><p class="modal-fine">Token research is live on mainnet and works without holding a token.</p><a class="secondary-button" href="#/methodology" data-action="token-methodology">How the app works ${icon('arrow')}</a>`),
 'token-methodology':()=>{closeModal();navigate('/methodology');},
'view':el=>{view=el.dataset.view;if(route()==='/')home();else if(route()==='/watchlist')watchlist();else if(route().startsWith('/search'))searchPage();},
'market-tab':el=>{activeMarket=el.dataset.tab;home();},
'refresh-market':()=>{loadMarket(true);home();},
'watch':el=>toggleWatch(el.dataset.address),
'retry-watchlist':()=>watchlist(),
'retry-search':()=>searchPage(),
'retry-report':el=>startInvestigation(el.dataset.address,true),
'copy':async el=>{try{await navigator.clipboard.writeText(el.dataset.value);toast('Copied to clipboard.');}catch{toast('Clipboard is unavailable in this browser. You can select and copy the address.');}},
'connect-wallet':()=>walletModal(),
'choose-wallet':el=>connectWallet(el.dataset.provider),
'disconnect-wallet':async()=>{const p=walletProvider;walletDisconnected();try{await p?.disconnect();}catch{}toast('Wallet disconnected.');},
'refresh-balance':()=>refreshBalance(),
'close-modal':()=>closeModal(),
'export-library':()=>{download('proof-protocol-research-'+new Date().toISOString().slice(0,10)+'.json',{app:'Proof Protocol',ticker:'PROOF',schema:1,exportedAt:new Date().toISOString(),network:'solana-mainnet',checks:storage.checks,watchlist:storage.watch});toast('Research library exported.');},
'export-report':el=>{const r=reports.get(el.dataset.address);if(r)download('proof-protocol-'+r.token.symbol.replace(/[^a-z0-9]/gi,'').slice(0,15)+'-'+r.address.slice(0,6)+'.json',r);},
'clear-library':()=>openModal('Clear this research library?',`<p>This removes all ${storage.checks.length} saved investigations and ${storage.watch.length} bookmarks from this browser. Export a copy first if you want to keep them.</p><div class="button-row"><button class="secondary-button" data-action="close-modal">Keep my research</button><button class="primary-button" data-action="confirm-clear">Clear local data</button></div>`),
'confirm-clear':()=>{persist('checks',[]);persist('watch',[]);reports.clear();closeModal();account();toast('Local research library cleared.');},
'delete-report':el=>{const address=el.dataset.address;persist('checks',storage.checks.filter(r=>r.address!==address));reports.delete(address);checks();toast('Saved report deleted.');}
};
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){const action=actions[el.dataset.action];if(action){e.preventDefault();Promise.resolve(action(el)).catch(()=>toast('That action could not complete. Please try again.'));}}});
document.addEventListener('submit',e=>{if(e.target.id==='scan-form'||e.target.id==='project-search'){e.preventDefault();submitQuery(new FormData(e.target).get('query'));}});
document.addEventListener('change',e=>{if(e.target.id==='theme-setting'){persist('theme',e.target.value);applySettings();}if(e.target.id==='density-setting'){persist('density',e.target.value);applySettings();}});
document.addEventListener('input',e=>{if(e.target.id==='history-filter')$('#history-list').innerHTML=investigationList();});
$('#theme-toggle').addEventListener('click',()=>{persist('theme',storage.theme==='dark'?'light':'dark');applySettings();});


function quickSearch(){if(route()==='/'){$('#scan-input')?.focus();$('#scan-input')?.scrollIntoView({block:'center',behavior:'smooth'});}else{navigate('/');setTimeout(()=>$('#scan-input')?.focus(),50);}}

$('#modal-overlay').addEventListener('click',e=>{if(e.target===$('#modal-overlay'))closeModal();});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();quickSearch();}if(e.key==='Escape'){if(!$('#modal-overlay').hidden)closeModal();}if(e.key==='Tab'&&!$('#modal-overlay').hidden){const items=$$('#modal button:not([disabled]),#modal a,#modal input,#modal select');const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',render);
if(location.pathname==='/me'&&!location.hash)location.hash='/me';
render();
